:root {
  --bg: #1e2430;
  --card: #2b3445;
  --text: #f2f5f9;
  --muted: #a9b4c4;
  --accent: #4cc9f0;
  --accent-dark: #3aa8cc;
  --danger: #ff5c5c;
  --bar-food: #f4a261;
  --bar-rent: #e76f51;
  --bar-fun: #2a9d8f;
  --bar-other: #8e7dbe;
}

* {
  box-sizing: border-box;
}

[hidden] {
  display: none !important;
}

body {
  margin: 0;
  min-height: 100vh;
  display: flex;
  align-items: center;
  justify-content: center;
  padding: 24px 16px;
  background: var(--bg);
  color: var(--text);
  font-family: system-ui, -apple-system, "Segoe UI", Roboto, sans-serif;
  font-size: 16px;
  line-height: 1.5;
}

.card {
  width: 100%;
  max-width: 520px;
  background: var(--card);
  border-radius: 18px;
  padding: 24px 20px 28px;
  box-shadow: 0 18px 40px rgba(0, 0, 0, 0.35);
}

h1 {
  margin: 0 0 20px;
  font-size: 1.6rem;
  letter-spacing: 0.02em;
}

.section {
  margin-bottom: 22px;
}

.section-title {
  margin: 0 0 10px;
  font-size: 1rem;
  font-weight: 600;
  color: var(--muted);
  text-transform: uppercase;
  letter-spacing: 0.08em;
}

.field {
  display: flex;
  flex-direction: column;
  gap: 6px;
  margin-bottom: 12px;
}

label {
  font-size: 0.95rem;
  color: var(--muted);
}

input,
select {
  width: 100%;
  padding: 12px 14px;
  font-size: 1rem;
  font-family: inherit;
  color: var(--text);
  background: #222a37;
  border: 2px solid #3a4558;
  border-radius: 10px;
  transition: border-color 0.15s ease, box-shadow 0.15s ease;
}

input:hover,
select:hover {
  border-color: var(--accent);
}

input:focus-visible,
select:focus-visible,
button:focus-visible {
  outline: none;
  border-color: var(--accent);
  box-shadow: 0 0 0 3px rgba(76, 201, 240, 0.35);
}

.expense-form {
  display: flex;
  flex-wrap: wrap;
  gap: 12px;
  align-items: flex-end;
}

.expense-form .field {
  flex: 1 1 140px;
  margin-bottom: 0;
}

.btn {
  font-family: inherit;
  font-size: 1rem;
  font-weight: 600;
  padding: 12px 18px;
  border: none;
  border-radius: 10px;
  cursor: pointer;
  transition: background 0.15s ease, transform 0.1s ease;
}

.btn-primary {
  background: var(--accent);
  color: #08222b;
}

.btn-primary:hover {
  background: var(--accent-dark);
}

.btn-primary:active {
  transform: translateY(1px);
}

.btn-delete {
  background: transparent;
  color: var(--danger);
  border: 2px solid var(--danger);
  padding: 6px 10px;
  font-size: 0.9rem;
}

.btn-delete:hover {
  background: rgba(255, 92, 92, 0.15);
}

.btn-delete:active {
  transform: translateY(1px);
}

.error {
  margin: 10px 0 0;
  color: var(--danger);
  font-size: 0.95rem;
}

.remaining {
  margin: 0;
  font-size: 2rem;
  font-weight: 700;
  color: var(--accent);
}

.remaining.negative {
  color: var(--danger);
}

.bars {
  display: flex;
  flex-direction: column;
  gap: 10px;
}

.bar-row {
  display: flex;
  align-items: center;
  gap: 10px;
}

.bar-label {
  flex: 0 0 64px;
  font-size: 0.95rem;
  color: var(--muted);
}

.bar-track {
  flex: 1;
  height: 14px;
  background: #222a37;
  border-radius: 7px;
  overflow: hidden;
}

.bar-fill {
  height: 100%;
  border-radius: 7px;
  transition: width 0.25s ease;
}

.bar-food { background: var(--bar-food); }
.bar-rent { background: var(--bar-rent); }
.bar-fun { background: var(--bar-fun); }
.bar-other { background: var(--bar-other); }

.bar-value {
  flex: 0 0 78px;
  text-align: right;
  font-size: 0.95rem;
  color: var(--text);
}

.expense-list {
  list-style: none;
  margin: 0;
  padding: 0;
  display: flex;
  flex-direction: column;
  gap: 8px;
}

.expense-item {
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 10px;
  padding: 10px 12px;
  background: #222a37;
  border-radius: 10px;
  font-size: 0.95rem;
}

.expense-info {
  display: flex;
  flex-wrap: wrap;
  gap: 6px 12px;
}

.expense-category {
  font-weight: 600;
}

.expense-amount {
  color: var(--muted);
}

.empty-state {
  margin: 0;
  color: var(--muted);
  font-size: 0.95rem;
}

@media (max-width: 420px) {
  .expense-form {
    flex-direction: column;
    align-items: stretch;
  }
  .bar-label {
    flex-basis: 48px;
  }
  .bar-value {
    flex-basis: 64px;
  }
}

(function () {
  'use strict';

  var CATEGORIES = ['Food', 'Rent', 'Fun', 'Other'];

  var state = {
    income: 0,
    expenses: []
  };

  var incomeInput = document.getElementById('income-input');
  var expenseForm = document.getElementById('expense-form');
  var categorySelect = document.getElementById('category-select');
  var amountInput = document.getElementById('amount-input');
  var errorMessage = document.getElementById('error-message');
  var remainingAmount = document.getElementById('remaining-amount');
  var barsContainer = document.getElementById('bars-container');
  var barsEmpty = document.getElementById('bars-empty');
  var expenseList = document.getElementById('expense-list');
  var listEmpty = document.getElementById('list-empty');

  function formatMoney(value) {
    return '$' + value.toFixed(2);
  }

  function totalExpenses() {
    return state.expenses.reduce(function (sum, expense) {
      return sum + expense.amount;
    }, 0);
  }

  function categoryTotals() {
    var totals = {};
    CATEGORIES.forEach(function (category) {
      totals[category] = 0;
    });
    state.expenses.forEach(function (expense) {
      totals[expense.category] += expense.amount;
    });
    return totals;
  }

  function showError(message) {
    errorMessage.textContent = message;
    errorMessage.hidden = false;
  }

  function clearError() {
    errorMessage.textContent = '';
    errorMessage.hidden = true;
  }

  function renderRemaining() {
    var remaining = state.income - totalExpenses();
    remainingAmount.textContent = formatMoney(remaining);
    remainingAmount.classList.toggle('negative', remaining < 0);
  }

  function renderBars() {
    var totals = categoryTotals();
    var max = 0;
    CATEGORIES.forEach(function (category) {
      if (totals[category] > max) {
        max = totals[category];
      }
    });

    barsContainer.textContent = '';

    if (max === 0) {
      barsEmpty.hidden = false;
      return;
    }
    barsEmpty.hidden = true;

    CATEGORIES.forEach(function (category) {
      var value = totals[category];
      var percent = Math.max(0, Math.min(100, (value / max) * 100));

      var row = document.createElement('div');
      row.className = 'bar-row';

      var label = document.createElement('span');
      label.className = 'bar-label';
      label.textContent = category;

      var track = document.createElement('div');
      track.className = 'bar-track';

      var fill = document.createElement('div');
      fill.className = 'bar-fill bar-' + category.toLowerCase();
      fill.style.width = percent + '%';
      track.appendChild(fill);

      var valueEl = document.createElement('span');
      valueEl.className = 'bar-value';
      valueEl.textContent = formatMoney(value);

      row.appendChild(label);
      row.appendChild(track);
      row.appendChild(valueEl);
      barsContainer.appendChild(row);
    });
  }

  function renderExpenseList() {
    expenseList.textContent = '';

    if (state.expenses.length === 0) {
      listEmpty.hidden = false;
      return;
    }
    listEmpty.hidden = true;

    state.expenses.forEach(function (expense) {
      var item = document.createElement('li');
      item.className = 'expense-item';

      var info = document.createElement('span');
      info.className = 'expense-info';

      var category = document.createElement('span');
      category.className = 'expense-category';
      category.textContent = expense.category;

      var amount = document.createElement('span');
      amount.className = 'expense-amount';
      amount.textContent = formatMoney(expense.amount);

      info.appendChild(category);
      info.appendChild(amount);

      var deleteButton = document.createElement('button');
      deleteButton.type = 'button';
      deleteButton.className = 'btn btn-delete';
      deleteButton.textContent = 'Delete';
      deleteButton.setAttribute('aria-label', 'Delete ' + expense.category + ' expense of ' + formatMoney(expense.amount));
      deleteButton.addEventListener('click', function () {
        removeExpense(expense.id);
      });

      item.appendChild(info);
      item.appendChild(deleteButton);
      expenseList.appendChild(item);
    });
  }

  function render() {
    renderRemaining();
    renderBars();
    renderExpenseList();
  }

  function removeExpense(id) {
    state.expenses = state.expenses.filter(function (expense) {
      return expense.id !== id;
    });
    render();
  }

  function addExpense(event) {
    event.preventDefault();
    clearError();

    var category = categorySelect.value;
    var rawAmount = amountInput.value.trim();
    var amount = parseFloat(rawAmount);

    if (!CATEGORIES.includes(category)) {
      showError('Please choose a valid category.');
      return;
    }
    if (rawAmount === '' || isNaN(amount) || amount <= 0) {
      showError('Please enter a positive amount greater than zero.');
      amountInput.focus();
      return;
    }

    state.expenses.push({
      id: Date.now() + '-' + Math.random().toString(16).slice(2),
      category: category,
      amount: Math.round(amount * 100) / 100
    });

    amountInput.value = '';
    amountInput.focus();
    render();
  }

  function updateIncome() {
    var value = parseFloat(incomeInput.value);
    state.income = isNaN(value) || value < 0 ? 0 : Math.round(value * 100) / 100;
    render();
  }

  incomeInput.addEventListener('input', updateIncome);
  expenseForm.addEventListener('submit', addExpense);

  render();
})();
